MAP
    NAME "SS_MAP_RURAL_LOCALIDAD_COBERTURA_PIPAS"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB  
    SYMBOL
        NAME "GotaAgua"
        TYPE pixmap
        IMAGE"includes/symbols/GotaAgua.png"
    END #SYMBOL
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_cobertura_pipas.txt"
    DEBUG 0
    LAYER
        PROJECTION
		 'init=epsg:32614'
		END #PROJECTION
        NAME "SS_MAP_RURAL_LOCALIDAD_COBERTURA_PIPAS"
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        DATA "gm_localidad_rural from public.l_localidad_rural using unique id_elemento_geografico using srid=32614"
        #DATA "gm_localidad_rural from (SELECT id_elemento_geografico, cl_principal_suministro FROM public.l_localidad_rural where cl_principal_suministro =2) as subquery USING UNIQUE id_elemento_geografico USING SRID=32614"
        TYPE POLYGON
        CLASS
        NAME "cobertura pipas"
        EXPRESSION ([cl_principal_suministro] = 2)  
        LABEL
            STYLE
                SYMBOL "GotaAgua"  # Tu símbolo definido
                SIZE 20  # Tamaño del icono
                COLOR 0 100 255  # Color (si aplica)
            END
        END
    END
    END #LAYER
END #MAP
